  char lettre = 0 ; // Stocke la lettre proposée par l'utilisateur (retour du scanf) char motSecret [ 100 ] = { 0}; // Ce sera le mot à trouver int * lettreTrouvee = NULL ; // Un tableau de booléens. Chaque case correspond à une lettre du mot secret. 0 = lettre non trouvée, 1 = lettre trouvée long coupsRestants = 10 ; // Compteur de coups restants (0 = mort) long i = 0; // Une petite variable pour parcourir les tableaux long tailleMot = 0;

  printf ( "Bienvenue  dans  le  Pendu  !         \n\n  " );

  if (! piocherMot (motSecret ))
    exit(0);

  tailleMot = strlen ( motSecret );

  lettreTrouvee = malloc ( tailleMot * sizeof ( int )); // On alloue
