coupsRestants );
    printf (" \n Quel  est  le  mot  secret  ?  " );

    /* On affiche le mot secret en masquant les lettres non
trouvées
Exemple : *A**ON */
    for (i = 0 ; i < tailleMot ; i++ )
    {
      if (lettreTrouvee [ i]) // Si on a trouvé la lettre n° i
        printf("%c", motSecret [ i]); // On l'affiche else printf("*"); // Sinon, on affiche une étoile pour les lettres non trouvées }

    printf (" \n Proposez  une  lettre  :  " );
