  {
    positionEntree = strchr ( chaine , '\n' );
    if ( positionEntree != NULL )
    {
      *positionEntree = '\0' ;
    }
    else
    {
      viderBuffer ();
    }
    return 1;
  }
  else
  {
    viderBuffer ();
    return 0;
  }
}

